package com.gomgomapps.math.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.util.regex.*;import java.io.*;
public class NumberPatternRelationsTest {
 static int parityValue(String prompt){Matcher m=Pattern.compile("^([0-9]+)(?: ([+−-]) ([0-9]+))?(?:은|의 값은) 짝수인가요, 홀수인가요\\?$").matcher(prompt);assertTrue(prompt,m.matches());int first=Integer.parseInt(m.group(1));return m.group(2)==null?first:m.group(2).equals("+")?first+Integer.parseInt(m.group(3)):first-Integer.parseInt(m.group(3));}
 static int answer(Question q){if(q.skillId.equals("el_even_odd"))return parityValue(q.prompt)%2;if(q.prompt.contains(" → ")){String[] terms=q.prompt.split("\\n")[0].split(" → ");int blank=Arrays.asList(terms).indexOf("□"),first=Integer.parseInt(terms[0]),second=Integer.parseInt(terms[1]);return q.skillId.equals("el_repeat_pattern")?Integer.parseInt(terms[blank%2]):first+blank*(second-first);}Matcher m=Pattern.compile("^(□|[0-9]+) ([+−-]) (□|[0-9]+) = ([0-9]+)$").matcher(q.prompt);assertTrue(m.matches());boolean first=m.group(1).equals("□");int known=Integer.parseInt(m.group(first?3:1)),result=Integer.parseInt(m.group(4));return m.group(2).equals("+")?result-known:first?result+known:known-result;}
 @Test public void publicRelationshipsRemainVariedAndIndependentOfKeys(){Generator g=new Generator(new Random(99210));for(String id:NumberPatternRelations.IDS){Set<String> prompts=new HashSet<>();for(int i=0;i<1200;i++){Question q=g.next(id,List.of(),i%2==0);String signature=q.signature();String[] answers=q.answers.clone();List<String> choices=new ArrayList<>(q.choices);int value=answer(q);assertEquals(""+value,q.answers[0]);prompts.add(q.prompt);HelpPlan p=HelpPlan.forQuestion(q);assertFalse(p.canTransfer());assertEquals(signature,q.signature());assertArrayEquals(answers,q.answers);assertEquals(choices,q.choices);var frames=NumberPatternRelations.frames(q);assertFalse(frames.isEmpty());assertEquals(""+value,frames.get(frames.size()-1).expected());for(int k=0;k<frames.size();k++){var f=frames.get(k);assertTrue(p.step(k).accepts(f.expected()));assertFalse(p.step(k).accepts(""));String wrong=f.options().isEmpty()?""+(Integer.parseInt(f.expected())+1):f.expected().equals("0")?"1":"0";assertFalse(p.step(k).accepts(wrong));assertTrue(f.label(),!f.label().matches(".*[0-9].*")||f.label().equals("2 × 둘씩 묶은 묶음 수 = "));assertTrue(Integer.parseInt(f.expected())>=0);}q.answers=new String[]{"999999"};q.expression="999999+1";q.studyGuide=new StudyGuide().step("old","999999 = ","","999999");HelpPlan corrected=HelpPlan.forQuestion(q);assertFalse(corrected.canTransfer());assertEquals(""+value,q.studyGuide.frames.get(corrected.size()-1).expected);}assertTrue(id+": "+prompts.size(),prompts.size()>=100);}}
 @Test public void smallRangesAndBothDirectionsArePreserved(){Generator g=new Generator(new Random(99211));boolean pure=false,add=false,sub=false,up=false,down=false;Set<Integer> positions=new HashSet<>();for(int i=0;i<1200;i++){Question q=g.next("el_even_odd",List.of(),false,new CurriculumLimits("wholeMaximum=8"));int total=parityValue(q.prompt);assertTrue(total>=1&&total<=8);Matcher nums=Pattern.compile("[0-9]+").matcher(q.prompt);while(nums.find())assertTrue(Integer.parseInt(nums.group())<=8);pure|=!q.prompt.contains("의 값");add|=q.prompt.contains(" + ");sub|=q.prompt.contains(" − ");q=g.next("el_sequence_10000",List.of(),false);String[] terms=q.prompt.split("\\n")[0].split(" → ");int first=Integer.parseInt(terms[0]),second=Integer.parseInt(terms[1]);up|=second>first;down|=second<first;for(String term:terms)if(!term.equals("□"))assertTrue(Integer.parseInt(term)>=100&&Integer.parseInt(term)<=10000);var frames=NumberPatternRelations.frames(q);assertEquals(""+Math.abs(second-first),frames.get(3).expected());assertEquals(""+answer(q),frames.get(4).expected());q=g.next("el_repeat_pattern",List.of(),false);terms=q.prompt.split("\\n")[0].split(" → ");positions.add(Arrays.asList(terms).indexOf("□"));for(String term:terms)if(!term.equals("□"))assertTrue(Integer.parseInt(term)>=1&&Integer.parseInt(term)<=9);}assertTrue(pure&&add&&sub&&up&&down);assertEquals(Set.of(2,3,4,5),positions);for(String prompt:List.of("1 → 2 → □ → 99","1 → □ → 3 → 4","1 → 2 → □ → □","5 - □ = 8")){String id=prompt.contains("→")?"el_number_pattern":"el_missing_sub";assertTrue(NumberPatternRelations.frames(new Question(id,prompt,"","0")).isEmpty());}}
 @Test public void oldDraftResetsAndNewPartialDraftRestores()throws Exception{Generator g=new Generator(new Random(99212));for(String id:NumberPatternRelations.IDS){Question q=g.next(id,List.of(),false);q.studyGuide=new StudyGuide().step("old","999 = ","","999");HelpPlan p=HelpPlan.forQuestion(q);HelpPlan.Draft old=new HelpPlan.Draft();old.questionId=q.id;old.stage=1;old.entries.add("999");assertEquals(0,p.restore(old,q.id).stage);HelpPlan.Draft d=p.restore(null,q.id);d.entries.set(0,q.studyGuide.frames.get(0).expected);d.stage=1;d.entries.add("");ByteArrayOutputStream bytes=new ByteArrayOutputStream();new ObjectOutputStream(bytes).writeObject(d);HelpPlan.Draft loaded=(HelpPlan.Draft)new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray())).readObject();assertEquals(1,p.restore(loaded,q.id).stage);assertEquals(d.entries.get(0),p.restore(loaded,q.id).entries.get(0));}}
}
